pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    _bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let time_factor = (1.0 - step_index as f64 / total_items as f64).powi(3);
    let residual_weight = if bin_residual < mean_residual { 1.7 } else { 0.3 };
    let next_item_penalty = if next_item_size > post_residual + item_size { 1.2 } else { 0.0 };
    let fitting_bins_bonus = if fitting_bins_count > 2 { 0.8 } else { 0.0 };
    let dynamic_time_weight = step_index as f64 / (total_items * open_bins_count) as f64;

    let score = -(post_residual as f64 * residual_weight
        + next_item_penalty
        - fitting_bins_bonus
        + time_factor
        + dynamic_time_weight);

    score
}

